class CustomerFilterTest {

    private static final Customer ADA = new Customer(
            1000, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
    private static final Customer MAKINEN = new Customer(
            1009, "Jarno", "Mäkinen", "jarno@example.com", "Netherlands", CustomerStatus.PENDING);
    private static final Customer JOSEPHINE = new Customer(
            1035, "Joséphine", "Aaltonen", "josefine@example.com", "Portugal", CustomerStatus.CLOSED);

    @Test
    void anEmptyNameMatchesEveryCustomer() {
        assertTrue(filter("").asPredicate().test(ADA));
        assertTrue(filter("   ").asPredicate().test(ADA));
    }

    @Test
    void everyTermMustMatchTheFirstOrTheLastName() {
        assertTrue(filter("ada aal").asPredicate().test(ADA));
        assertTrue(filter("aal ada").asPredicate().test(ADA));
        assertFalse(filter("ada virtanen").asPredicate().test(ADA));
    }

    @Test
    void whitespaceAroundAndBetweenTermsIsNotSignificant() {
        assertTrue(filter("  ada \t  aal  ").asPredicate().test(ADA));
    }

    @Test
    void accentsAndCaseAreIgnoredInBothDirections() {
        assertTrue(filter("makinen").asPredicate().test(MAKINEN));
        assertTrue(filter("MAKINEN").asPredicate().test(MAKINEN));
        assertTrue(filter("mäkinen").asPredicate().test(MAKINEN));
        assertTrue(filter("josephine").asPredicate().test(JOSEPHINE));
        assertTrue(filter("JOSÉPHINE").asPredicate().test(JOSEPHINE));
    }

    @Test
    void noStatusSelectedKeepsEveryStatus() {
        assertTrue(new CustomerFilter("", Set.of()).asPredicate().test(MAKINEN));
    }

    @Test
    void selectedStatusesAreOrdAndOnlyKeepTheSelectedOnes() {
        CustomerFilter activeOrClosed = new CustomerFilter("", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));

        assertTrue(activeOrClosed.asPredicate().test(ADA));
        assertTrue(activeOrClosed.asPredicate().test(JOSEPHINE));
        assertFalse(activeOrClosed.asPredicate().test(MAKINEN));
    }

    @Test
    void nameAndStatusMustBothMatch() {
        CustomerFilter aalPending = new CustomerFilter("aal", Set.of(CustomerStatus.PENDING));

        assertFalse(aalPending.asPredicate().test(ADA));
        assertFalse(aalPending.asPredicate().test(JOSEPHINE));
        assertFalse(new CustomerFilter("mäkinen", Set.of(CustomerStatus.ACTIVE)).asPredicate().test(MAKINEN));
    }

    private static CustomerFilter filter(String name) {
        return new CustomerFilter(name, Set.of());
    }
}
